mapper.select:
SELECT id, create_time, name, effective_type, effective_days, start_time, end_time, product_type, coupon_type, discount, discount_amount, condition_amount, issue_quantity, limit_quantity, status, integral, COALESCE(s.total_used, 0) AS has_get, COALESCE(u.used_count, 0) AS has_use FROM t_coupon p LEFT JOIN ( SELECT coupon_id, COUNT(*) AS total_used FROM t_member_coupon WHERE is_deleted = 0 GROUP BY coupon_id ) s ON s.coupon_id = p.id LEFT JOIN ( SELECT coupon_id, COUNT(*) AS used_count FROM t_member_coupon WHERE use_status = 1 AND is_deleted = 0 GROUP BY coupon_id ) u ON u.coupon_id = p.id
p.is_deleted = 0
AND p.name LIKE CONCAT('%',#{couponParam.name},'%')
AND p.status = #{couponParam.status}
AND p.coupon_type = #{couponParam.couponType}
AND p.give_type = #{couponParam.giveType}
AND DATE_FORMAT(p.start_time,'%Y-%m-%d') >= #{couponParam.startTime}
AND DATE_FORMAT(p.end_time,'%Y-%m-%d') <= #{couponParam.endTime}
ORDER BY p.status, p.create_time desc

SELECT
FROM t_coupon p
p.is_deleted = 0 AND p.id = #{id}

mapper.update:
update
t_coupon p
set p.status = #{status}

    p.id = #{id}
